sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var orch = new x_fed_day2_ops.MacdrOrchestrator();
  var called = false;
  var r = orch.run(
    { requester_id: 'day2-requester-sysid', approver_id: 'day2-approver-sysid', verb: 'disableUser' },
    function () { called = true; return { ok: true }; },
    { action: 'disableUser', target: { userId: 'u1' } }
  );
  if (r.ok) { stepResult.setFailed('origin-less request was accepted (P0-6 regressed)'); return; }
  if (r.clause !== 'origin') { stepResult.setFailed('stopped at ' + r.clause + ', expected origin'); return; }
  if (called) { stepResult.setFailed('actuation ran despite no origin'); return; }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var orch = new x_fed_day2_ops.MacdrOrchestrator();
  var r = orch.run(
    { requester_id: 'day2-requester-sysid', approver_id: 'day2-approver-sysid',
      verb: 'disableUser', sam_request_id: 'IIQ-DOES-NOT-EXIST-0001' },
    function () { return { ok: true }; },
    { action: 'disableUser', target: { userId: 'u1' } }
  );
  if (r.ok || r.clause !== 'origin') {
    stepResult.setFailed('an unresolvable sam_request_id was treated as a valid origin');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
